UPDATE companies SET description='Wisconsin Steel Fabrication LLC operates from Omro, Wisconsin. It remains a family-owned business.

The shop provides steel fabrication and manufacturing services including large modular fabrication, small modular fabrication, structural steel, custom fabrication, railings and stairs, and certified welding. From its original garage, the operation has expanded to a 12-acre campus with a 25,000-square-foot facility housing modern equipment and an experienced staff.

Leadership emphasizes quality and on-time delivery as core differentiators, stating that customer satisfaction drives the business. The team promotes a willingness to tackle any project regardless of size, aiming to turn client ideas into finished fabrications.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Large Modular Fabrication", "Small Modular Fabrication", "Structural Steel", "Custom Fabrication", "Railings and Stairs", "Certified Welding"], "industries": ["Construction", "Modular Construction", "Residential"], "materials": ["Steel"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Quality and on-time delivery", "Customer satisfaction focus", "Handles projects of any size", "Family-owned and operated"], "facts_used": ["Location: Omro, Wisconsin -> /", "Family-owned, founded by two brothers from Berlin, WI -> /", "Started in 900 sq ft backyard garage -> /", "Facility: 12-acre, 25,000 sq ft -> /", "Services: Large Modular Fabrication, Small Modular Fabrication, Structural Steel, Custom Fabrication, Railings and Stairs, Certified Welding -> /services", "Industries: construction, modular, residential repair -> /", "Differentiators: quality, on-time delivery, customer satisfaction, any project size -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Wisconsin Steel Fabrication LLC is a steel fabrication and manufacturing company in Omro, Wisconsin.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='wisconsin-steel-fabrication-llc' AND approved AND profile IS NULL;
UPDATE companies SET description='Wisconsin Wire Works, Inc. operates from Wales, Wisconsin, where five copper-industry veterans founded the company in 1994.

The company manufactures copper and copper alloy welding wire, including aluminum bronze, silicon bronze, deoxidized copper, phosphor bronze, nickel aluminum bronze, and copper alloy brazing wires. Production centers on state-of-the-art drawing equipment maintained on a scheduled die-rework program, with a thorough inspection program that checks size, cleanliness, cast, and helix before any product ships. An in-house welding facility and a staff of welding engineers, metallurgists, and fabrication specialists provide technical support and product testing.

Customers span welders, fabricators, and manufacturers on every continent. The wire is supplied in precision layer-level wound spools, straightened-and-cut lengths, reels, coils, and barrel packs, all packaged in robust cartons with hermetic moisture barriers for long shelf life and secure international shipment.

The founders built the company on listening to customers — staying small enough to know them well and surveying them regularly. That approach, combined with a commitment to made-in-the-USA quality, non-contaminating lubricants, minimal landfill waste, and thorough cleaning before shipment, is what the company says sets it apart.', certifications=ARRAY['ISO 9001:2000','ABS certified supplier']::text[], profile='{"capabilities": ["Copper and copper alloy welding wire drawing", "Precision layer-level spooling", "Straightened and cut lengths", "Reel and coil packaging", "Barrel pack packaging", "Hermetic moisture-barrier cartoning", "In-house welding test facility", "Technical support and metallurgical consultation", "Quality inspection for size, cleanliness, cast, and helix", "Scheduled drawing die maintenance"], "industries": ["Welding", "Fabrication", "Manufacturing"], "materials": ["Copper", "Aluminum Bronze", "Silicon Bronze", "Deoxidized Copper", "Phosphor Bronze", "Nickel Aluminum Bronze", "Copper Alloy Brazing Wires"], "equipment": ["State-of-the-art drawing equipment", "Drawing dies"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Precision layer-level wound spools for smooth robotic feeding", "Scheduled die rework \u2014 not just when worn \u2014 for surface quality", "No product ships unless it meets size, cleanliness, cast, and helix standards", "Exclusive use of non-contaminating lubricants and thorough pre-shipment cleaning", "Hermetic moisture-barrier packaging for extended shelf life", "In-house welding facility staffed by welding engineers and metallurgists"], "facts_used": ["Founded 1994 by five copper-industry veterans -> /", "Headquarters Wales, Wisconsin -> /", "Leadership: John Turriff (President/Owner), Tressa Turriff (VP), Ryan Turriff (VP), Jeremy Hoadley (Sales Manager) -> /", "Products: aluminum bronze, silicon bronze, deoxidized copper, phosphor bronze, nickel aluminum bronze, copper alloy brazing wires -> /", "Manufacturing: drawing equipment, scheduled die rework, inspection for size/cleanliness/cast/helix -> /", "Packaging: precision layer-level wound spools, straightened-cut lengths, reels, coils, barrel packs, hermetic moisture-barrier cartons -> /", "Certifications: ISO 9001-2000 (Cert A2541US), ABS certified supplier -> /", "Services: in-house welding facility, welding engineers, metallurgists, fabrication specialists -> /", "Environmental: non-contaminating lubricants, minimal landfill, thorough cleaning -> /", "Customer base: welders, fabricators, manufacturers on every continent -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "integrated manufacturer of copper and copper alloy welding wire", "founded_year": "1994", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='wisconsin-wire-works-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Wise Plastics Technologies traces its roots to 1974, when it was founded as Wise‑Hamlin Plastics in the greater Chicagoland area. Today the company is headquartered in St. Charles, Illinois, with additional facilities in West Chicago, placing it roughly 30 minutes from downtown Chicago and O’Hare International Airport.

The molder operates more than 100 injection presses ranging from 35 to 1,100 tons across three purpose‑built plants totaling over 350,000 square feet. Core processes include precision plastic injection molding, two‑shot, insert and over‑molding, liquid silicone rubber (LSR) molding for medical‑grade and biocompatible applications, and scientific molding supported by RJG‑certified decoupled processes and automation on every cell. Value‑added services span assembly, sonic welding, heat staking, decorating, packaging, kitting, and full contract‑manufacturing programs that cover tooling transfers, design‑for‑manufacturing, supply‑chain management, and just‑in‑time delivery. A staff of 200+ runs production 24/5, shifting to 24/7 when demand requires.

The company serves medical device and pharmaceutical customers with ISO 13485:2016‑certified quality systems and clean‑room LSR capability, defense programs under ITAR registration, and a broad range of industrial OEMs that rely on its integrated supply‑chain and logistics support.

Wise Plastics emphasizes five decades of manufacturing discipline, modern equipment, and a quality‑first culture codified in ISO 9001:2015 and OSHA SHARP certifications. Its stated differentiators include purpose‑built facilities, integrated operations, advanced automation, an experienced team, ultra‑responsive service, and a commitment to continuous improvement across quality, innovation, employee respect, integrity, and sustainability.', certifications=ARRAY['ISO 9001:2015','ISO 13485:2016','ITAR Registered','OSHA SHARP Certified']::text[], profile='{"capabilities": ["Plastic Injection Molding", "Two-shot Injection Molding", "Insert Molding", "Over-Molding", "In-Mold Labeling (IMD/IML)", "RJG Scientific Molding", "Decoupled Molding\u00ae Processes", "Liquid Silicone Rubber Molding", "Medical Grade LSR", "Clean Room Manufacturing", "Tooling Transfers", "International Tool Transfers", "Domestic Mold Relocation", "Tool Refurbishment & Repair", "Contract Manufacturing", "Design for Manufacturing (DFM)", "Supply Chain Management", "Just-in-Time Delivery", "Assembly Services", "Sonic Welding", "Heat Staking", "Printing & Decorating", "Packaging Solutions", "Quality Inspection"], "industries": ["Medical Devices", "Pharmaceutical", "Defense/Aerospace (ITAR)", "Industrial OEMs"], "materials": ["Medical-grade resins", "Liquid Silicone Rubber (LSR)", "Biocompatible materials", "High-temperature resistant materials", "Engineering thermoplastics"], "equipment": ["100+ injection presses (35\u20131,100 tons)", "RJG Scientific Molding systems", "Decoupled Molding\u00ae processes", "CMM (Coordinate Measuring Machine) technology", "Automated part handling systems", "Clean room manufacturing cells"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Over 100 injection presses from 35 to 1,100 tons under one quality system", "Liquid silicone rubber (LSR) molding for medical\u2011grade, biocompatible parts", "Three purpose\u2011built Illinois facilities totaling 350,000+ sq. ft.", "Scientific molding 24/5 (24/7 on demand) with in\u2011process monitoring and automation on every cell", "Full turnkey contract manufacturing including tooling transfers, DFM, assembly, and logistics"], "facts_used": ["Founded 1974 as Wise-Hamlin Plastics -> /about", "Headquartered in St. Charles, Illinois -> /about", "Three facilities, 350,000+ sq ft -> /about", "100+ presses 35-1100 tons -> /", "200+ skilled employees -> /about", "ISO 9001:2015 certified -> /", "ISO 13485:2016 certified -> /", "ITAR registered -> /", "OSHA SHARP certified -> /about", "Liquid silicone rubber molding -> /services", "Two-shot, insert, over-molding -> /services", "Value-added operations: assembly, sonic welding, decorating, packaging -> /services", "Contract manufacturing with supply chain management -> /services", "Scientific molding 24/5 and 24/7 -> /", "RJG Scientific Molding, Decoupled Molding -> /services", "Clean room manufacturing -> /services", "Tooling transfers domestic and international -> /services", "Engineering services: DFM, rapid prototyping, mold design -> /services", "Quality lab with CMM -> /services"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Wise Plastics Technologies is a full turnkey contract manufacturing company headquartered in St. Charles, Illinois \u2014 only 30 minutes from Chicago and O''Hare \u2014 specializing in custom plastic injection molding, liquid silicone injection molding (LSR), and value-added secondary operations.", "founded_year": "1974", "employee_count": "200+", "cage_code": "", "min_order": "", "export_compliance": ["ITAR registered"], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='wise-plastics' AND approved AND profile IS NULL;
UPDATE companies SET description='The company was established to address unmet needs in pediatric orthopedics, focusing on children who are still growing.

The company designs and supplies anatomically appropriate implants and instruments packaged as single-use, sterile procedure kits. Its product lines include growth control systems, plating systems, and bone void fillers, all delivered in multi-barrier sterile packaging. Instruments such as screwdrivers and depth gauges are included in each kit, eliminating the need for reusable trays and loaner sets.

Its kits are used in procedures for children with orthopedic conditions, providing a sterile, ready-to-use alternative to traditional reusable instrument sets.

The company emphasizes that its single-use model reduces infection risk, cuts operating room turnover time by eliminating set reprocessing, and avoids the logistical burden of loaner trays. Every instrument is new and sharp for each procedure, and kits are stocked for immediate availability.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Single-use sterile procedure kit assembly", "Multi-barrier sterile packaging", "Pediatric orthopedic implant manufacturing", "Instrument manufacturing", "Growth control system design", "Plating system design", "Bone void filler formulation"], "industries": ["Pediatric orthopedics", "Medical devices", "Orthopedic implants", "Healthcare"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Single-use sterile procedure kits eliminate reprocessing", "Multi-barrier sterile packaging ensures component sterility", "Instruments are new and sharp for every procedure", "No loaner trays required; kits are stocked for immediate use", "Reduces OR turnover time by removing set processing"], "facts_used": ["Headquarters: Warsaw, Indiana -> db", "Product focus: pediatric orthopedic implants and instruments in single-use sterile kits -> /", "Product lines: growth control, plating system, bone void filler -> /", "Sterile packaging: multi-barrier sterile packaging -> /", "Instruments included: screwdriver, depth gauge -> /", "Differentiators: no loaner trays, kits stocked, reduce OR turnover, eliminate set processing -> /", "Target customers: pediatric orthopedic surgeons, hospitals, surgical centers -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "WishBone Medical provides anatomically appropriate implants and instruments in single-use, sterile packed procedure kits.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='wishbone-medical-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Wolf Metals operates from Columbus, Ohio, where it was founded in 1974 by Jim and Mike Wolf as a family-owned metal fabrication shop. Over three decades, the company has grown from a small local operation into a full-service fabrication specialist serving customers across the United States.

The company provides a broad range of metal fabrication processes under one roof, including laser cutting, water jet cutting, forming (bending, rolling, stamping), shearing, MIG and TIG welding, fastener insertion, powder coating, plating, assembly, CNC machining, leveling, tube laser cutting, laser welding, and aluminum composite material (ACM) fabrication. Its 100,000-square-foot facility houses more than 50 state-of-the-art machines, such as CNC machining centers, robotic welding cells, laser cutting systems, and a fully automated robotic bend cell. Wolf Metals handles projects from one-off prototypes to large production runs.

The shop serves industries including automotive, aerospace, defense, energy, medical, agriculture, construction, and industrial machinery. A recent project involved engineering a modular aluminum exoskeleton for DTi Creative, enabling marching bands to transform a John Deere Gator into performance vehicles such as a lunar rover and a pirate ship.

Wolf Metals emphasizes uncompromising quality, continuous innovation, customer focus, integrity, and teamwork as core values. The company cites a 99.8% on-time delivery rate and a defect rate below 0.1% as measurable outcomes of its approach, and highlights its centrally located Ohio facility for efficient nationwide service.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Laser Cutting", "Water Jet Cutting", "Forming (bending, rolling, stamping)", "Shearing", "MIG & TIG Welding", "Fastener Insertion", "Powder Coating", "Plating", "Assembly", "CNC Machining", "Leveling", "Tube Laser Cutting", "Laser Welding", "Fully Automated Robotic Bend Cell", "Aluminum Composite Material (ACM) Fabrication"], "industries": ["Automotive", "Aerospace", "Defense", "Energy", "Medical", "Agriculture", "Construction", "Industrial Machinery"], "materials": ["Aluminum", "Aluminum Composite Material (ACM)"], "equipment": ["CNC machining centers", "robotic welding cells", "laser cutting systems", "tube laser cutting equipment", "water jet cutting equipment", "fully automated robotic bend cell"], "volume": "One-off custom pieces to large production runs", "lead_time": "", "tolerances": "", "built_on": ["End-to-end fabrication solutions under one roof", "100,000+ sq ft facility with 50+ state-of-the-art machines", "99.8% on-time delivery rate and <0.1% defect rate", "Family-owned since 1974 with decades of combined team experience", "Centrally located in Columbus, Ohio for efficient U.S. service"], "facts_used": ["Founded in 1974 by Jim and Mike Wolf -> /about-us", "Family-owned company -> /about-us", "Headquarters at 1625 W Mound St, Columbus, OH 43223 -> /about-us", "100,000+ sq ft manufacturing space -> /services", "50+ state-of-the-art machines -> /services", "99.8% on-time delivery rate -> /services", "<0.1% defect rate -> /services", "Industries served: Automotive, Aerospace, Defense, Energy, Medical, Agriculture, Construction, Industrial Machinery -> /about-us", "Capabilities: laser cutting, water jet cutting, forming, shearing, MIG/TIG welding, fastener insertion, powder coating, plating, assembly, CNC machining, leveling, tube laser cutting, laser welding, fully automated robotic bend cell, ACM fabrication -> /services", "Case study: modular aluminum exoskeleton for DTi Creative -> /services", "End-to-end solutions under one roof -> /about-us", "State-of-the-art CNC machining, laser cutting, and welding equipment -> /about-us", "Jim Wolf Founder & CEO, Mike Wolf Operations Manager, Pat Wolf Equipment Operator -> /about-us", "Core values: Uncompromising Quality, Innovation, Customer Focus, Integrity, Teamwork -> /about-us"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Wolf Metals has been at the forefront of custom metal fabrication in Ohio for over three decades.", "founded_year": "1974", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='wolf-metals' AND approved AND profile IS NULL;
UPDATE companies SET description='Wolfe Custom Woodworking LLC operates from Englewood, Colorado, serving the Denver metropolitan area. The company was founded by Daniel E. Wolfe, who has spent many years crafting fine furniture and cabinets before establishing the business as a full-service design, fabrication, and installation shop.

The shop specializes in built-in cabinetry, custom shelving, and stand-alone hardwood tables and casework. Recent projects include a white oak banquette and dining table, a walnut banquette, a mid-century modern media credenza, a solid walnut bookshelf, a shaker hutch, and a modern side table featuring a bookmatched Indian rosewood top with bowtie joints and hand-carved bevel.

Wolfe emphasizes a hands-on approach: each piece is designed and fabricated with his own two hands, and he encourages clients to participate in the design process so the final product reflects their exact vision. This personal involvement and focus on long-lasting quality are presented as the core reasons the business exists.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Design", "Fabrication", "Installation", "Custom cabinetry", "Shelving", "Table making", "Casework", "Furniture making", "Joinery", "Hand carving"], "industries": [], "materials": ["White Oak", "Walnut", "Indian Rosewood", "North American Black Walnut", "Vinyl", "Hardwood"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Location: Englewood, Colorado -> db", "Founder: Daniel E. Wolfe -> /about-us", "Business description: full service design, fabrication and installation shop serving the Denver Metro Area -> / and /about-us", "Specialties: built-in cabinetry, shelving, stand-alone hardwood tables and casework -> / and /about-us", "Projects: White Oak Banquette & Dining Room Table, Vinyl Casework, Walnut Banquette, Mid Century Modern Media Credenza, Mid Century Modern Solid Walnut Bookshelf, Shaker Hutch, Modern Side Table -> /services", "Materials: White Oak, Walnut, Indian Rosewood, North American Black Walnut, Vinyl -> /services", "Differentiator: each project designed and fabricated by founder personally -> /about-us", "Differentiator: client participation in design process encouraged -> /about-us", "Contact: phone , email  -> / and /about-us"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "full service design, fabrication and installation shop; Each project is carefully designed and fabricated with my own two hands", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, 