UPDATE companies SET description='Wyoming Authentic Beef operates from Cody, Wyoming, where it produces a line of grass-fed Angus beef jerky, sticks, and bites.

The business manufactures whole-muscle jerky and formed snacks using beef sourced from Wyoming ranches. Each package identifies the specific ranch of origin, and recipes are limited to nine ingredients or fewer with no added hormones, antibiotics, MSG, nitrites, nitrates, or artificial ingredients. Facility size, headcount, and production volumes are not disclosed.

Products are sold direct-to-consumer through the company''s e-commerce site with free shipping on orders over $75 (excluding Alaska and Hawaii).

The company emphasizes traceability and ingredient simplicity as its differentiators: every bag names the Wyoming ranch that supplied the cattle, and the ingredient deck stays at nine items or less. A published "Code of the West" underscores values such as keeping promises, finishing what is started, and knowing where to draw the line.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Whole-muscle beef jerky production", "Formed beef stick manufacturing", "Beef bite/snack production", "Small-batch seasoning and marination", "Retail packaging with ranch-of-origin labeling"], "industries": ["Food & beverage manufacturing", "Meat processing", "Snack foods", "Specialty retail", "Direct-to-consumer e-commerce"], "materials": ["Grass-fed Angus beef", "Natural spices and seasonings"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Ranch-level traceability printed on every package", "Nine ingredients or fewer per product", "No added hormones, antibiotics, MSG, nitrites, nitrates, or artificial ingredients", "100% grass-fed Angus beef sourced from Wyoming ranches"], "facts_used": ["Headquarters in Cody, Wyoming -> db", "Produces grass-fed Angus beef jerky, sticks, and bites -> /", "Beef sourced from Wyoming ranches with ranch name on each package -> /", "Recipes use 9 ingredients or fewer, no hormones/antibiotics/MSG/nitrites/nitrates/artificial ingredients -> /", "Direct-to-consumer e-commerce with free shipping over $75 -> /", "Published ''Code of the West'' values -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Each bag of our whole-muscle Angus Beef Jerky proudly displays the name of the Wyoming Ranch where the beef was locally sourced and is made with just 9 ingredients or less.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='wyoming-authentic-beef' AND approved AND profile IS NULL;
UPDATE companies SET description='Wyoming Fudge Company, LLC operates from Gillette, Wyoming, where it opened its doors on January 12, 2025. The business is the second act for founder Kristy Sims, who previously ran a fudge shop in Pinedale before dedicating three decades to an office supply store.

The company produces handcrafted fudge in small batches, using real butter, fresh cream, and time-honored recipes. Its Gillette facility was renovated with updated plumbing, electrical, and permitting to support production. The line includes assortments such as cheesecake, candy-inspired, and chocolate swirl flavors, sold directly to consumers and through wholesale channels. The firm also offers custom-branded gift boxes, dessert displays for corporate events, and a fundraising program for schools and non-profits.

Customers range from local boutiques, gift shops, and specialty markets that stock the fudge on shelves, to corporate clients seeking branded gifts for clients and guests. The wholesale program promises attractive margins and reliable local delivery. Fundraising partners include schools, sports teams, and non-profit organizations that run profitable community sales.

Sims says the company was restarted to fulfill a lifelong passion for premium sweets and to bring a taste of the West to the table. The small-batch method, real ingredients, and community-focused initiatives—including Ataxia awareness driven by the family’s experience—are cited as what sets the operation apart.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Small-batch fudge production", "Handcrafted confectionery", "Wholesale distribution", "Custom-branded gift packaging", "Corporate gift and event dessert displays", "Fundraising program management"], "industries": ["Retail", "Wholesale", "Corporate gifting", "Event catering", "Fundraising (non-profit)", "Specialty food"], "materials": ["Real butter", "Fresh cream", "Chocolate", "Pecans", "Blueberries", "Strawberries", "Banana", "M&Ms", "Toffee", "Butterfinger", "Amaretto flavoring", "Mint flavoring", "Caramel", "Peanut butter", "Birthday cake flavoring"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Handcrafted in small batches in Gillette, Wyoming", "Made with real butter and fresh cream using time-honored recipes", "Wholesale program with attractive margins and reliable local delivery", "Custom-branded gift boxes and dessert displays for corporate events", "Fundraising program for schools, sports teams, and non-profits"], "facts_used": ["Founded by Kristy Sims -> db description", "Female-owned small business -> db description", "Located in Gillette, Wyoming -> db hq_city, hq_state_label", "Soft opening January 12, 2025 -> /about page", "Previous fudge shop in Pinedale -> /about page", "Sold office supply store in 2025 after 30+ years -> /about page", "Handcrafted small-batch fudge with real butter and fresh cream -> home page and description", "Wholesale partnerships with attractive margins and local delivery -> home page", "Custom-branded gift boxes and dessert displays for corporate events -> home page", "Fundraising program for schools, sports teams, non-profi