UPDATE companies SET description='Youngtron Inc is an electronic contract manufacturer based in Hatfield, Pennsylvania, near Philadelphia. The company was established in 1988 to provide the electronics industry with assembly services covering surface mount, through-hole, and complete product assembly.

Youngtron operates a 24,000‑square‑foot facility designed around automated surface‑mount and through‑hole equipment, offering full turnkey PCB assembly, customer‑supplied kit assembly, box build, in‑circuit and functional testing, fine‑pitch and BGA/µBGA placement, automated vision inspection, conformal coating, and turnkey procurement. The shop handles both RoHS and non‑RoHS processes.

Youngtron emphasizes a quality management system registered to ISO 9001 and compliant with IPC‑A‑610 Class 2 standards, promising consistent high quality, fast flexible turnaround, competitive pricing, reliable personal service, accurate communication, and on‑time delivery. The firm was founded on the principle that quality and communication drive long‑term customer relationships.', certifications=ARRAY['ISO 9001','RoHS','IPC-A-610 Class 2']::text[], profile='{"capabilities": ["Automated surface mount assembly", "Fine-pitch and BGA/\u00b5BGA placement", "Automated through-hole assembly", "RoHS and non-RoHS assembly", "In-circuit testing", "Functional testing", "Automated vision inspection", "Conformal coating", "Turnkey procurement", "Box build", "Full turnkey assembly", "Customer-supplied kit assembly"], "industries": [], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["ISO 9001 registered quality management system", "24,000 sq ft facility designed for automated assembly", "BGA/\u00b5BGA placement expertise", "Full turnkey procurement and box build services", "Commitment to on-time delivery and consistent quality"], "facts_used": ["Founded 1988 -> /about", "Location Hatfield, PA -> /", "24,000 sq ft facility -> /about", "ISO 9001 registered -> /about", "Capabilities: automated surface mount, through-hole, conformal coating, box build, turnkey -> /services", "RoHS and non-RoHS assembly -> /services", "In-circuit and functional testing -> /services", "Fine-pitch and BGA/\u00b5BGA placement -> /services", "Automated vision inspection -> /services", "IPC-A-610 Class 2 compliance -> /about", "Quality management system based on continuous improvement -> /about", "Company description as contract manufacturer -> db"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "We are a full service, ISO 9001 registered, contract manufacturer of electronic assemblies located in Hatfield Penns